program2='''def transform(grid):
    h, w = len(grid), len(grid[0])
    occupied = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    options = []
    for r in range(h - 1):
        for c in range(w - 1):
            block = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            if set(block) <= occupied:
                options.append((set(block), 1))
            for missing, color in ((0, 2), (2, 3), (1, 4)):
                piece = set(block) - {block[missing]}
                if piece <= occupied:
                    options.append((piece, color))

    def cover(remaining, chosen):
        if not remaining:
            return chosen
        cell = min(remaining, key=lambda p: sum(p in piece and piece <= remaining for piece, _ in options))
        for piece, color in options:
            if cell in piece and piece <= remaining:
                result = cover(remaining - piece, chosen + [(piece, color)])
                if result is not None:
                    return result
        return None

    solution = cover(occupied, [])
    if solution is None:
        return [list(row) for row in grid]
    output = [[0 for _ in range(w)] for _ in range(h)]
    for piece, color in solution:
        for r, c in piece:
            output[r][c] = color
    return output
'''
